import React, { useState, useEffect, useRef } from "react";
import { MpaIcon } from "../icon/MpaIcon";
import { TextField } from "../textField";
import "./Dropdown.scss";
import { SvgMpaIcon } from "../../assets/icons";

export interface DropdownOption {
  value: string;
  label: string;
}

export interface DropdownProps {
  /**
   * Identifying value for the dropdown.
   */
  id: string;
  /**
   * Label to be displayed above the dropdown list.
   */
  label?: string;
  /**
   * List of dropdown options. Must be provided in a dictionary of key-value pairs.
   */
  options: DropdownOption[];
  /**
 * Property from DropdownOption to return from onChange. Defaults to value.
 */
  valueKey?: "label" | "value";
  /**
   * The initial value in the dropdown list.
   */
  selectedValue?: string;
  /**
   * Supporting text to display below the component.
   */
  supportingText?: string;

  /**
   * Text to display under the dropdown in case of an error.
   */
  errorText?: string;

  /**
   * Text to be displayed in a help tooltip next to the label.
   */
  tooltipText?: string;
   /**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?: "right" | "left" | "top" | "bottom";
   /**
    * React SVG icon object to be displayed in a help tooltip next to the label.
    */
  tooltipIcon?: keyof typeof SvgMpaIcon | string;

  /**
   * Custom onChange function that can be overrided.
   */
  onChange?: (value: string) => void;
   /**
   * Placeholder text to be displayed when no option is selected.
   */
  placeholder?: string;
  /**
   * Boolean that determines if the dropdown can be interacted with.
   */
  disabled?: boolean;
  /**
   * Boolean that determines if a clear button appears when an option is selected.
   */
  clearable?: boolean;
  /**
   * Boolean that determines if options can be searched.
   */
  searchable?: boolean;

  /**
   * Boolean that determines if error styling is enabled.
   */
  error?: boolean;
  /**
   * Determines the colour palette of the dropdown.
   */
  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;
}

const Dropdown: React.FC<DropdownProps> = ({
  id,
  label,
  options,
  valueKey = "value",
  selectedValue,
  supportingText,
  errorText,
  tooltipText,
  tooltipPlacement="top",
  tooltipIcon,
  onChange,
  placeholder = "Select...",
  disabled = false,
  clearable = true,
  error = false,
  searchable = false,
  colour = "primary",
  className,
}) => {
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedOption, setSelectedOption] = useState<DropdownOption | undefined>(undefined);

  // Ensure options is always an array
  const safeOptions: DropdownOption[] = Array.isArray(options) ? options : [];

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  // Sync selectedOption when selectedValue or options change
  useEffect(() => {
    const selected = safeOptions.find((opt) => opt[valueKey] === selectedValue);
    setSelectedOption(selected);
  }, [selectedValue, safeOptions, valueKey]);

  const displayValue = selectedOption?.label ?? placeholder;

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(event.target.value);
  };

  const handleOptionClick = (option: DropdownOption) => {
    setSelectedOption(option);
    setIsOpen(false);
    onChange?.(option[valueKey]);
  };

  const handleClearClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedOption(undefined);
    onChange?.("");
    setSearchQuery("");
  };

  const toggleDropdown = () => {
    if (!disabled) {
      setIsOpen((prev) => !prev);
    }
  };

  const filteredOptions = searchQuery
    ? safeOptions.filter((option) =>
        option.label.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : safeOptions;

  const getHoverClass = () => {
    return isHovered ? `form-dropdown-hover-${colour}` : "";
  };

  return (
    <div
      ref={dropdownRef}
      className={`dropdown container ${isOpen ? "expanded" : ""} ${className || ""}`}
      id={id}
      role="listbox"
      aria-expanded={isOpen}
    >
      <div className="form-single-dropdown">
        {label &&(
          <div className="single-dropdown-label-div">
            <label className="single-dropdown-label">{label}</label>
            { tooltipText && tooltipText.trim().length > 0 && tooltipIcon && (
                <MpaIcon
                  colour="var(--mpa-gray)"
                  iconName={tooltipIcon}
                  tooltipText={tooltipText}
                  tooltipPlacement={tooltipPlacement}
                />
              )
            }
          </div>
        )}

        <div
          className={`single-dropdown-text ${disabled ? "single-dropdown-text-disabled" : ""}
            ${error ? "single-dropdown-text-error" : ""} ${getHoverClass()}`}
          onClick={toggleDropdown}
          onFocus={() => setIsHovered(true)}
          onBlur={() => setIsHovered(false)}
          tabIndex={0}
        >
          {displayValue}
          <div className="single-dropdown-icon-container">
            <span className="single-dropdown-icon">
              {clearable && selectedOption && (
                <span className="single-dropdown-clear-icon" onClick={handleClearClick}>
                  <MpaIcon iconName="X" />
                </span>
              )}
              <MpaIcon iconName={isOpen ? "ChevronUp" : "ChevronDown"} />
            </span>
          </div>
        </div>

        {isOpen && (
          <div className="single-dropdown-options">
            {searchable && (
              <div className="single-dropdown-search-input-container">
                <TextField
                  id="search-input"
                  type="text"
                  placeholder="Search"
                  leadingIcon="Search"
                  value={searchQuery}
                  onChange={handleSearchChange}
                  className="single-dropdown-search"
                  clearable
                />
              </div>
            )}
            <ul className="single-dropdown-list">
              {filteredOptions.length === 0 ? (
                <li className="single-dropdown-no-options">No options found</li>
              ) : (
                filteredOptions.map((option) => (
                  <li
                    key={option.value}
                    className="single-dropdown-dropdown-item"
                    onClick={() => handleOptionClick(option)}
                  >
                    {option.label}
                  </li>
                ))
              )}
            </ul>
          </div>
        )}
      </div>

      {!isOpen && !error && supportingText && (
        <div className="single-dropdown-supporting-text">{supportingText}</div>
      )}

      {!isOpen && error && errorText && (
        <div className="single-dropdown-error-text">
          <span className="dropdown-error-icon">
            <MpaIcon iconName="AlertCircle" />
          </span>
          {errorText}
        </div>
      )}
    </div>
  );
};

export default Dropdown;
